 build=load(ROOT/'out/BUILD.json');checks=load(ROOT/'out/ROW_CHECKS.json');gt=load(ROOT/'out/GT_CHECK.json');raster=load(ROOT/'out/RASTER_CHECK.json');audit=load(ROOT/'out/room_audit_final_v2/audit.json');dev=load(ROOT/'out/DEV_S1_DIAGNOSTIC.json');extra=load(ROOT/'out/EXTRA_CHECKS.json');name=load(ROOT/'out/NAME_PRIOR.json')
